          problems.push({el: card.querySelector(".add-opt"), msg: `${loc}：单选题至少需要两个选项。`});
        }
        q.options = values;
      }
      payloadQuestions.push(q);
    });
    return {problems, payload: {title, description: descArea.value, questions: payloadQuestions}};
  }

