def update_survey(self, survey_id):
    # 先确认记录存在，不存在直接 404，绝不创建
    exists = database.execute(
        "SELECT 1 FROM surveys WHERE id = ?", (survey_id,)
    ).fetchone()
    if exists is None:
        self.respond(404, {"error": "not found"})
        return
    try:
        length = int(self.headers.get("Content-Length") or 0)
    except ValueError:
        length = -1
    if length < 0:
        self.respond(400, {"error": "Content-Length 无效"})
        return
    if length > MAX_BODY_BYTES:
        self.respond(400, {"error": "请求体过大"})
        return
    body = self.rfile.read(length) if length else b""
    try:
        payload = json.loads(body.decode("utf8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        self.respond(400, {"error": f"请求体不是合法 JSON：{error}"})
        return

    clean, error = validate_survey(payload)
    if error is not None:
        self.respond(400, {"error": error})
        return
    try:
        updated = update_survey(survey_id, clean)
    except sqlite3.DatabaseError as error:
        self.respond(500, {"error": f"保存失败：{error}"})
        return
    if not updated:
        self.respond(404, {"error": "not found"})
        return
    self.respond(200, survey_detail(survey_id))
