            allowed = ["GET"]
        elif detail_match:
            allowed = ["GET", "PUT"]
        else:
            self.respond(404, {"error": "not found"})
            return

        if self.command not in allowed:
            self.respond(405, {"error": "method not allowed"}, allow=allowed)
            return

        if location == "/":
            self.respond(200, PAGE, html=True)
        elif location == "/health":
            self.respond(200, {"status": "ok", "product": PRODUCT})
        elif location == "/api/surveys":
            if self.command == "POST":
                self.create_survey()
            else:
                self.list_surveys()
        elif self.command == "PUT":
            self.replace_survey(int(detail_match.group(1)))
        else:
            detail = survey_detail(int(detail_match.group(1)))
            if detail is None:
                self.respond(404, {"error": "not found"})
            else:
                self.respond(200, detail)

