import base64, json, os, socket, struct, subprocess, time, urllib.request

CHROME = "/usr/bin/google-chrome"
PORT = 9227
proc = subprocess.Popen([CHROME, "--headless=new", "--no-sandbox", "--disable-gpu",
                         f"--remote-debugging-port={PORT}", "--user-data-dir=/tmp/os-test/cdp-profile6",
                         "about:blank"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
try:
    for _ in range(50):
        try:
            targets = json.load(urllib.request.urlopen(f"http://127.0.0.1:{PORT}/json"))
            break
        except Exception:
            time.sleep(0.1)
    target = next(t for t in targets if t["type"] == "page")

    class WS:
        def __init__(self, url):
            host, path = url[5:].split("/", 1)
            self.sock = socket.create_connection((host.split(":")[0], int(host.split(":")[1])))
            key = base64.b64encode(os.urandom(16)).decode()
            req = (f"GET /{path} HTTP/1.1\r\nHost: {host}\r\nUpgrade: websocket\r\n"
                   f"Connection: Upgrade\r\nSec-WebSocket-Key: {key}\r\nSec-WebSocket-Version: 13\r\n\r\n")
            self.sock.sendall(req.encode())
            assert b"101" in self.sock.recv(4096).split(b"\r\n", 1)[0]
            self.buf = b""; self._id = 0
        def _send_frame(self, payload):
            data = payload.encode()
            mask = os.urandom(4)
            masked = bytes(b ^ mask[i % 4] for i, b in enumerate(data))
            n = len(data)
            header = b"\x81" + (bytes([0x80 | n]) if n < 126 else bytes([0x80 | 126]) + struct.pack(">H", n))
            self.sock.sendall(header + mask + masked)
        def send(self, method, params=None):
            self._id += 1
            msg = {"id": self._id, "method": method}
            if params: msg["params"] = params
            self._send_frame(json.dumps(msg))
            return self._id
        def recv(self, timeout=10):
            self.sock.settimeout(timeout)
            while True:
                if self.buf and len(self.buf) >= 2:
                    b1, b2 = self.buf[0], self.buf[1]
                    ln = b2 & 0x7F; idx = 2
                    if ln == 126: ln = struct.unpack(">H", self.buf[2:4])[0]; idx = 4
                    elif ln == 127: ln = struct.unpack(">Q", self.buf[2:10])[0]; idx = 10
                    if len(self.buf) >= idx + ln:
                        frame = self.buf[idx:idx+ln]; self.buf = self.buf[idx+ln:]
                        return json.loads(frame.decode())
                chunk = self.sock.recv(65536)
                if not chunk: raise EOFError
                self.buf += chunk
        def close(self): self.sock.close()

    ws = WS(target["webSocketDebuggerUrl"])
    def evaljs(expr):
        mid = ws.send("Runtime.evaluate", {"expression": expr, "awaitPromise": True, "returnByValue": True})
        while True:
            msg = ws.recv()
            if msg.get("id") == mid: return msg
    def navigate(url):
        mid = ws.send("Page.navigate", {"url": url})
        while True:
            msg = ws.recv()
            if msg.get("id") == mid: return

    navigate("http://127.0.0.1:8077/#/surveys/1/edit")
    time.sleep(1.5)
    r = evaljs("""
      new Promise((resolve) => {
        document.querySelector('#app input[type=text]').value = '取消前的乱改';
        // 取消编辑 is the 3rd .btn.secondary in row-actions
        const btns = document.querySelectorAll('#app .row-actions .btn.secondary');
        resolve(JSON.stringify({count: btns.length, thirdText: btns[2].textContent}));
      })
    """)
    print("BTNS:", r["result"]["result"].get("value"))
    r = evaljs("""
      new Promise((resolve) => {
        const btns = document.querySelectorAll('#app .row-actions .btn.secondary');
        btns[2].click();
        setTimeout(() => resolve(JSON.stringify({
          hash: location.hash,
          h2: document.querySelector('#app h2')?.textContent
        })), 800);
      })
    """)
    print("CANCEL:", r["result"]["result"].get("value"))
    ws.close()
finally:
    proc.terminate(); proc.wait(timeout=5)
EOF
